    {
        _statusStrip = new StatusStrip();

        // .NET 9 breaking change: StatusStrip now defaults to system rendering
        // instead of professional rendering. Restore the .NET 8 appearance.
        _statusStrip.RenderMode = ToolStripRenderMode.ManagerRenderMode;

        _statusStrip.Items.Add(new ToolStripStatusLabel("Ready"));
        Controls.Add(_statusStrip);
    }

    /// <summary>
    /// Shows an editor dropdown, guarding against the .NET 9 breaking change
    /// where DropDownControl now throws ArgumentNullException on null.
    /// </summary>
    public void ShowDropDown(IWindowsFormsEditorService editorService, Control dropDown)
    {
        if (dropDown is null)
            return;

        editorService.DropDownControl(dropDown);
    }
}

